let db={categories:{Gold:['All pieces'],Silver:['All pieces']},products:[],cart:[...new Map(savedBag.filter(c=>/^[0-9a-f-]{36}$/i.test(c.id)).map(c=>[c.id,{id:c.id,qty:1}])).values()].slice(0,50),orders:[],rates:{'22K':NaN,'18K':NaN,'925':NaN},gst:base.gst,delivery:base.delivery,categoryCovers:{},categorySearchResults:{}};
let categoryRows=[],settingsRow=null,metadataReady=false,metadataError='',catalogueLoading=false,catalogueError='',catalogueResult={items:[],count:0},catalogueRequest=0,mutationBusy=false;
const categoryRow=(m,c)=>categoryRows.find(r=>r.metal===m&&r.name===c);
const categoryCount=(m,c)=>Number(categoryRow(m,c)?.product_count||0);
function cacheProducts(items){const keep=db.products.filter(p=>db.cart.some(c=>c.id===p.id)||p.id===activeProduct?.id);db.products=[...new Map([...keep,...items].map(p=>[p.id,p])).values()]}
async function loadMetadata(){const result=await inventory.metadata();categoryRows=result.categories;settingsRow=result.settings;db.categories={Gold:['All pieces'],Silver:['All pieces']};for(const row of categoryRows)db.categories[row.metal].push(row.name);db.rates={'22K':Number(settingsRow.gold_22),'18K':Number(settingsRow.gold_18),'925':Number(settingsRow.silver_925)};db.gst=Number(settingsRow.gst);db.delivery=Number(settingsRow.delivery);db.rateUpdated=settingsRow.updated_at;metadataReady=true;metadataError=''}
async function loadCataloguePage(){if(!metadataReady||!['catalog','detail'].includes(currentRoute?.screen))return;const request=++catalogueRequest;catalogueLoading=true;catalogueError='';render();try{const result=await inventory.products({metal,category,page:pageNumber,search:$('#search').value,sort:$('#sort').value});if(request!==catalogueRequest)return;const pages=Math.max(1,Math.ceil(result.count/PAGE_SIZE));if(pageNumber>pages){pageNumber=pages;return loadCataloguePage()}catalogueResult=result;cacheProducts(result.items)}catch(error){if(request===catalogueRequest){catalogueError=error.message;catalogueResult={items:[],count:0}}}finally{if(request===catalogueRequest){catalogueLoading=false;render()}}}
async function syncCatalogue(){try{await loadMetadata();render();await loadCataloguePage()}catch(error){metadataError=error.message;render();throw error}}
async function onlineChange(task,after){if(!isAdmin()||mutationBusy)return;mutationBusy=true;const controls=[...document.querySelectorAll('#modal button,#modal input,#modal select,#modal textarea')];const states=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);let saved=false;try{await task();saved=true;await syncCatalogue();if(after)await after();return true}catch(error){if(saved){closeModal();toast('Saved online, but the catalogue could not refresh. Reload the page to see your change.');return true}toast(error.message);return false}finally{mutationBusy=false;controls.forEach((c,i)=>c.disabled=states[i])}}
sessionStorage.removeItem('lk-role');
let role='',metal='Gold',category='All pieces',activeProduct=null,galleryIndex=0,editorPhotos=[],editorOriginals=[],editorId=null,returnFocus=null;
// Management visibility follows the verified account and server-controlled admin record.
const isAdmin=()=>Boolean(auth.state.user && auth.state.admin);
function persist(){try{localStorage.setItem('lk-bag-v2',JSON.stringify(db.cart));return true}catch{toast('Your bag could not be saved on this device.');return false}}
function price(p){const value=p.weight*db.rates[p.purity];const shop=p.chargeType==='fixed'?p.charge:p.chargeType==='gram'?p.weight*p.charge:value*p.charge/100;return {value,shop,total:value+shop}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(title,content,subtitle=''){modalKind=null;returnFocus=document.activeElement;$('#modalContent').innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p class="modal-subtitle">${esc(subtitle)}</p>`:''}</div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
let modalKind=null;
let pendingAccountAction=null,otpEmail='',authAttempt=0;
const preferredName=()=>auth.state.preferredName;
function closeModal(){pendingAccountAction=null;authAttempt++;$('#modal').close();if(currentRoute?.screen==='detail'){navigate(routePath(metal,category));return}returnFocus?.focus()}
function login(next='account'){
 pendingAccountAction=next;authAttempt++;
 if(!window.LK_AUTH_CONFIG.emailOtpEnabled){modal('Customer accounts are opening soon',`<p>You can browse our collections and keep your favourites in your bag. Email sign-in is being connected.</p><p>For help with a piece, call <a href="tel:+919840763243">+91 98407 63243</a>.</p><button class="primary" data-action="close">Keep browsing</button>`);return}
 modal('Sign in to continue',`<p>We’ll email you a one-time code. No password needed.</p><form id="signInForm"><div class="form-grid"><label class="full">Email address<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="you@example.com"></label></div><p class="auth-error" id="authError" role="alert"></p><button class="primary" type="submit">Send sign-in code <span>↗</span></button></form><p><button class="text-button" data-action="close">Keep browsing</button></p>`);
 const form=$('#signInForm');form.onsubmit=async e=>{e.preventDefault();const email=form.elements.email.value.trim(),attempt=authAttempt;const button=form.querySelector('button');button.disabled=true;$('#authError').textContent='';try{await auth.sendCode(email);if(attempt!==authAttempt)return;otpEmail=email;showCodeForm()}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
}
function showCodeForm(){
 const sentAt=Date.now();
 modal('Check your email',`<p>Enter the sign-in code sent to <strong>${esc(otpEmail)}</strong>.</p><form id="codeForm"><div class="form-grid"><label class="full">One-time code<input name="code" required pattern="[0-9]{6,10}" minlength="6" maxlength="10" inputmode="numeric" autocomplete="one-time-code" placeholder="Enter your code"></label></div><p class="auth-error" id="authError" role="alert"></p><button class="primary" type="submit">Verify and continue <span>↗</span></button></form><p><button class="text-button" id="resendCode">Resend code</button> · <button class="text-button" id="changeEmail">Use another email</button></p>`);
 const form=$('#codeForm');form.onsubmit=async e=>{e.preventDefault();const attempt=authAttempt,button=form.querySelector('button');button.disabled=true;$('#authError').textContent='';try{await auth.verifyCode(otpEmail,form.elements.code.value);if(attempt!==authAttempt)return;if(preferredName())resumeAccountAction();else askPreferredName()}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
 $('#changeEmail').onclick=()=>login(pendingAccountAction||'account');
 $('#resendCode').onclick=async e=>{if(Date.now()-sentAt<60000){$('#authError').textContent='Please wait a minute before requesting another code.';return}const button=e.currentTarget,attempt=authAttempt;button.disabled=true;try{await auth.sendCode(otpEmail);if(attempt===authAttempt){showCodeForm();toast('A new code has been sent.')}}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
}
function resumeAccountAction(){const next=pendingAccountAction;pendingAccountAction=null;if(next==='checkout')checkout();else if(next==='orders')orders();else account()}
function askPreferredName(next){
 if(!role)return login(next||'account');if(next)pendingAccountAction=next;
 modal('What should we call you?',`<p>Tell us your preferred name so we can address you comfortably when discussing your order.</p><form id="preferredNameForm"><div class="form-grid"><label class="full">Preferred name<input id="preferredName" name="preferredName" value="${esc(preferredName())}" required maxlength="80" placeholder="e.g. Laksh" autocomplete="nickname" aria-describedby="nameNote"></label></div><p id="nameNote">Saved to your account. You can change it here anytime.</p><p class="auth-error" id="authError" role="alert"></p><button class="primary" type="submit">Save and continue <span>↗</span></button></form>`);
 const input=$('#preferredName');input.oninput=()=>input.setCustomValidity('');
 $('#preferredNameForm').onsubmit=async e=>{e.preventDefault();const name=input.value.trim().replace(/\s+/g,' ');if(!name){input.setCustomValidity('Please enter the name you’d like us to use.');input.reportValidity();return}const button=e.currentTarget.querySelector('button'),attempt=authAttempt;button.disabled=true;$('#authError').textContent='';try{await auth.saveName(name);if(attempt===authAttempt)resumeAccountAction()}catch(error){if(attempt===authAttempt)$('#authError').textContent=error.message}finally{button.disabled=false}};
}
async function signOut(){try{await auth.signOut();pendingAccountAction=null;authAttempt++;$('#modal').close();$('#modalContent').innerHTML='';render();toast('Signed out. You can keep browsing.')}catch(error){toast(error.message)}}
async function account(){if(!auth.state.ready){try{await auth.refresh()}catch(error){toast(error.message);return}}if(!role)return login();if(!preferredName())return askPreferredName('account');modal(isAdmin()?'Your admin account':'Your account',`<h3>Hello, ${esc(preferredName())}.</h3><p>${esc(auth.state.user.email)}</p><p>${isAdmin()?'Sole administrator':'Customer account'}</p><div class="admin-tabs">${isAdmin()?'<button data-action="dashboard">Manage shop</button>':''}<button data-action="orders">My orders</button><button data-action="editName">Edit preferred name</button></div><button class="secondary" data-action="signOut">Sign out</button>`)}
const PAGE_SIZE=12;
let currentRoute=null, currentKey='', pageNumber=1;
const viewMemory=new Map();
const routePath=(m,c,id)=>'#/'+[m,c,id].filter(Boolean).map(encodeURIComponent).join('/');
function readRoute(){let parts;try{parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean).map(decodeURIComponent)}catch{parts=[]}const [m,c,id]=parts;if(!db.categories[m])return {screen:'home'};if(!c||!db.categories[m].includes(c)||c==='All pieces')return {screen:'categories',metal:m};const p=db.products.find(p=>p.id===id&&p.metal===m&&p.category===c);return {screen:id?'detail':'catalog',metal:m,category:c,id:id||null}}
function rememberView(){if(currentKey)viewMemory.set(currentKey,{search:$('#search').value,sort:$('#sort').value,page:pageNumber,scroll:window.scrollY})}
function navigate(path,replace=false){rememberView();if(location.hash===path){applyRoute();return}history[replace?'replaceState':'pushState']({},'',path);applyRoute()}
function applyRoute(){pendingAccountAction=null;authAttempt++;if($('#modal').open)$('#modal').close();catalogueRequest++;currentRoute=readRoute();currentKey=location.hash||'#/';const saved=viewMemory.get(currentKey);$('#search').value=saved?.search||'';$('#sort').value=saved?.sort||'featured';pageNumber=saved?.page||1;render();if(currentRoute.screen==='detail')loadProductDetail(currentRoute.id);loadCataloguePage();requestAnimationFrame(()=>window.scrollTo({top:saved?.scroll||0,behavior:'instant'}))}
function goBack(){if(currentRoute.screen==='detail')navigate(routePath(metal,category));else if(currentRoute.screen==='catalog')navigate(routePath(metal));else navigate('#/')}
async function loadProductDetail(id){const expected=location.hash;modal('Loading jewellery…','<p>Please wait.</p>');try{const p=await inventory.product(id);if(location.hash!==expected||!$('#modal').open)return;if(!p){modal('This piece is no longer available','<button class="secondary" data-action="backCatalog">Back to collection</button>');return}cacheProducts([...catalogueResult.items,p]);drawProduct(id)}catch(error){if(location.hash===expected&&$('#modal').open)modal('Could not load this piece',`<p>${esc(error.message)}</p><button class="secondary" data-action="backCatalog">Back to collection</button>`)}}
function showProduct(id){const p=db.products.find(p=>p.id===id);if(!p)return;if($('#modal').open)$('#modal').close();if(currentRoute?.id===id){loadProductDetail(id);return}navigate(routePath(p.metal,p.category,p.id))}
function shopInfo(){modal('Visit L K Jewellers',$('#shopInfoTemplate').innerHTML)}
function render(){
 $('#adminNav').hidden=!isAdmin();document.querySelectorAll('.admin-only').forEach(e=>e.hidden=!isAdmin());
 $('.demo-label').textContent=rateState(settingsRow).label;$('#rateStatus').textContent=rateState(settingsRow).message;$('#bagCount').textContent=db.cart.reduce((sum,c)=>sum+c.qty,0);$('#year').textContent=new Date().getFullYear();$('#rateName').textContent=metal==='Gold'?'22K Gold':'Silver';$('#rateValue').textContent=money(db.rates[metal==='Gold'?'22K':'925']);
 const r=currentRoute||{screen:'home'};const home=r.screen==='home',cats=r.screen==='categories';if(r.metal)metal=r.metal;if(r.category)category=r.category;
 $('#homeScreen').hidden=!home;$('#categoryScreen').hidden=!cats;$('#catalogScreen').hidden=home||cats;$('#journeyNav').hidden=home;$('#searchBtn').hidden=home||cats;
 $('#breadcrumbs').innerHTML=`<button data-home>Home</button>${!home?`<span>/</span>${cats?`<span aria-current="page">${esc(metal)}</span>`:`<button data-metal="${metal}">${metal}</button><span>/</span><span aria-current="page">${esc(category)}</span>`}`:''}`;
 $('#backBtn').textContent=cats?'← Back to Gold / Silver':'← Back to categories';
 if(home){$('#products').innerHTML='';$('#categoryCards').innerHTML='';return}
 if(cats){$('#products').innerHTML='';if(!metadataReady){$('#categoryCards').innerHTML=`<div class="empty"><p>${esc(metadataError||'Loading collections…')}</p>${metadataError?'<button class="secondary" data-action="retryCatalogue">Retry</button>':''}</div>`;return}$('#categoryTitle').textContent=metal+' collections';$('#categoryCards').innerHTML=db.categories[metal].filter(c=>c!=='All pieces').map((c,i)=>{const count=categoryCount(metal,c);const cover=categoryCover(metal,c),img=cover.src;return `<div class="category-tile"><button class="category-card ${metal.toLowerCase()}-category" data-category="${esc(c)}"><span class="category-visual">${img?`<img class="${cover.license?'searched-category-image':''}" src="${esc(img)}" alt="" loading="lazy" decoding="async">`:`<span class="category-picture-status">${esc(cover.source)}</span>`}<span class="category-index">${String(i+1).padStart(2,'0')}</span></span><span class="category-caption"><span><strong>${esc(c)}</strong><small>${count?count+' '+(count===1?'piece':'pieces')+' to discover':'Collection coming soon'}</small></span><span aria-hidden="true">→</span></span></button></div>`}).join('')||'<div class="empty"><h3>A new collection awaits.</h3><p>Categories will appear here once the shop adds them.</p></div>';queueMicrotask(()=>ensureCategoryCovers(metal));return}
 $('#categoryCards').innerHTML='';$('#catalogTitle').textContent=category;$('#catalogMetal').textContent=metal.toUpperCase()+' COLLECTION';$('#rateName').textContent=metal==='Gold'?'22K Gold':'925 Silver';$('#rateValue').textContent=money(db.rates[metal==='Gold'?'22K':'925']);
 const query=$('#search').value.toLowerCase().trim();const products=catalogueResult.items;
 const pages=Math.max(1,Math.ceil(catalogueResult.count/PAGE_SIZE));const start=(pageNumber-1)*PAGE_SIZE;const visible=products;
 $('#resultCount').textContent=catalogueLoading?'Loading…':catalogueResult.count?`${start+1}–${Math.min(start+PAGE_SIZE,catalogueResult.count)} of ${catalogueResult.count} pieces`:'No pieces found';
 if(catalogueLoading||catalogueError){$('#products').innerHTML=`<div class="empty" role="status"><p>${esc(catalogueLoading?'Loading jewellery…':catalogueError)}</p>${catalogueError?'<button class="secondary" data-action="retryCatalogue">Retry</button>':''}</div>`;$('#pagination').innerHTML='';return}
 $('#products').innerHTML=visible.length?visible.map(p=>`<article class="product"><button class="product-img" data-product="${esc(p.id)}" aria-label="View ${esc(p.name)}"><span class="product-tag">${esc(p.isSample?'ILLUSTRATIVE SAMPLE':p.tag||'NEW TO THE COLLECTION')}</span><img src="${esc(p.photos[0]||'assets/hero.jpg')}" alt="${esc(p.name)}" loading="lazy" decoding="async"></button><div class="product-info"><small>${esc(p.purity)} ${esc(p.metal)} · ${p.weight} g</small><button class="product-name" data-product="${esc(p.id)}">${esc(p.name)}</button><div class="product-price"><span>${money(price(p).total)}</span><small>+ GST & delivery</small></div>${isAdmin()?`<div class="product-edit"><button class="text-button" data-edit="${esc(p.id)}">Edit jewel ↗</button><button class="text-button danger" data-delete="${esc(p.id)}">Delete</button></div>`:''}</div></article>`).join(''):`<div class="empty"><h3>${query?'No matching pieces.':'Something lovely is on its way.'}</h3><p>${query?'Try another search or clear the search box.':'This category is ready for the shop to add jewellery.'}</p><button class="secondary" data-action="backCategories">Back to categories</button></div>`;
 $('#pagination').innerHTML=pages>1?`<button class="secondary" data-page="${pageNumber-1}" ${pageNumber===1?'disabled':''}>← Previous</button><span>Page ${pageNumber} of ${pages}</span><button class="secondary" data-page="${pageNumber+1}" ${pageNumber===pages?'disabled':''}>Next →</button>`:'';
}

function policy(){modal('A little clarity, before you shop.',`<div class="eyebrow">OUR SHOPPING POLICY</div><h3>No bargaining.</h3><p>Prices are calculated from the applicable metal rate and the shop charge. GST and delivery charges are confirmed in the shop’s final quote.</p><h3>No change-of-mind returns.</h3><p>Please check the design, weight, size and description carefully before ordering.</p><h3>Incorrect or defective item?</h3><p>Keep a clear package-opening video or other appropriate evidence. The shop will review the issue and arrange the applicable resolution. A video is not the only acceptable form of proof. Applicable consumer rights remain unaffected.</p><h3>Delivery to your address or collection from shop</h3><p>Delivery availability, charges and timing will be confirmed before a real order is accepted. You can also collect your jewellery from the shop.</p><h3>Request first, pay after acceptance</h3><p>Choose “Deliver to my address” or “Collect from shop” and provide your full address. No payment is taken with the request. The shop reviews the design and time needed to make it, then issues a final quote including GST, delivery and an expected date. Check its expiry and cancellation terms before agreeing. A 20% advance will confirm the order once online payments are enabled; the remaining 80% is due upon delivery or when collecting from the shop.</p><p>Unpaid requests can be cancelled without charge. Expired quotes require a new quote. No advance payment is collected by this website yet.</p>`)}
const ist = value => value?new Date(value).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST':'Not yet available';
function rateNotice(){const state=rateState(settingsRow);return `<div class="notice">${esc(state.message)} · <a href="https://www.livechennai.com/gold_silverrate.asp" target="_blank" rel="noopener">Live Chennai ↗</a></div>`}
function rates(){modal('Understanding your jewellery price',`<p>Metal value + shop charge = jewellery price. GST and delivery are added at checkout.</p><div class="price-lines">${[['22K gold','22K','gold_22'],['18K gold','18K','gold_18'],['Silver','925','silver_925']].map(([name,key,field])=>`<div><span>${name}<small>Source updated: ${esc(ist(settingsRow?.rate_source_times?.[field]))}</small></span><strong>${money(db.rates[key])} / g</strong></div>`).join('')}</div>${rateNotice()}<p>Checked automatically every five minutes. Last successful check: ${esc(ist(settingsRow?.rate_checked_at))}.</p><p>Silver uses the listed silver rate directly, including 925 jewellery. 18K gold uses <a href="https://www.livechennai.com/18k_goldrate_chennai.asp" target="_blank" rel="noopener">Live Chennai’s 18K rate</a>. These are the source’s latest published prices, not a second-by-second market feed.</p>${isAdmin()?'<button class="primary" data-action="settings">Checkout settings</button>':''}`);modalKind='rates'}

function drawProduct(id){let p=db.products.find(p=>p.id===id);if(!p)return;activeProduct=p;galleryIndex=0;const v=price(p);modal(p.name,`<div class="detail-return"><button data-action="backCatalog" class="back-button">← Back to ${esc(p.category)}</button><button data-action="goHome" class="home-button">Home</button></div><div class="detail"><div><div class="gallery-main"><img id="mainPhoto" src="${esc(p.photos[0])}" alt="${esc(p.name)} — photo 1" data-action="zoom"><div class="gallery-control"><button data-action="prevPhoto" aria-label="Previous photo">←</button><span id="photoCounter">1 / ${p.photos.length}</span><button data-action="nextPhoto" aria-label="Next photo">→</button></div></div><div class="thumbs">${p.photos.map((photo,i)=>`<button data-photo="${i}" class="${i===0?'selected':''}" aria-label="Show photo ${i+1}"><img src="${esc(photo)}" alt="Photo ${i+1}"></button>`).join('')}</div><small>${p.isSample?'Illustrative sample · ':''}Tap image to enlarge</small></div><div><div class="eyebrow">${esc(p.purity)} ${esc(p.metal)} · ${p.weight} GRAMS</div><h2>${esc(p.name)}</h2><p>${esc(p.description||'Discover this piece in our collection.')}</p><div class="main-price">${money(v.total)}</div><small>Estimated jewellery amount · Final quote after shop review</small>${rateNotice()}<div class="price-lines"><div><span>Metal value<small>${p.weight} g × ${money(db.rates[p.purity])}/g</small></span><span>${money(v.value)}</span></div><div><span>Shop charge</span><span>${money(v.shop)}</span></div><div class="total"><span>Jewellery price</span><strong>${money(v.total)}</strong></div></div><button class="primary" data-add-bag="${esc(p.id)}">Add to bag <span>↗</span></button><div class="notice">No bargaining. No change-of-mind returns. Incorrect or defective items can be reviewed with suitable proof.</div></div></div>`);modalKind='product';let x=0;$('#mainPhoto').ontouchstart=e=>x=e.changedTouches[0].screenX;$('#mainPhoto').ontouchend=e=>{const dx=e.changedTouches[0].screenX-x;if(Math.abs(dx)>40)gallery(dx<0?galleryIndex+1:galleryIndex-1)}}
function gallery(i){if(!activeProduct)return;galleryIndex=(i+activeProduct.photos.length)%activeProduct.photos.length;$('#mainPhoto').src=activeProduct.photos[galleryIndex];$('#mainPhoto').alt=`${activeProduct.name} — photo ${galleryIndex+1}`;$('#photoCounter').textContent=`${galleryIndex+1} / ${activeProduct.photos.length}`;document.querySelectorAll('[data-photo]').forEach(e=>e.classList.toggle('selected',Number(e.dataset.photo)===galleryIndex))}
function addBag(id){if(db.cart.some(c=>c.id===id))return toast('This design is already in your bag.');if(db.cart.length>=50)return toast('Your bag can hold up to 50 different designs.');db.cart.push({id,qty:1});persist();render();toast('Added to your bag')}
function cartTotal(){return db.cart.reduce((sum,c)=>sum+price(db.products.find(p=>p.id===c.id)).total*c.qty,0)}
async function showBag(){try{await loadMetadata();const items=await inventory.byIds(db.cart.map(c=>c.id));db.products=[...db.products.filter(p=>!db.cart.some(c=>c.id===p.id)),...items]}catch(error){toast(error.message);return}db.cart=db.cart.filter(c=>db.products.some(p=>p.id===c.id));const total=cartTotal();modal('Your jewellery bag',db.cart.length?`${db.cart.map(c=>{const p=db.products.find(p=>p.id===c.id);return `<div class="bag-item"><img src="${esc(p.photos[0])}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>${esc(p.purity)} ${esc(p.metal)} · ${p.weight} g</p><button class="text-button" data-remove="${p.id}">Remove</button></div><strong>${money(price(p).total*c.qty)}</strong></div>`}).join('')}<div class="price-lines"><div class="total"><span>Jewellery subtotal</span><strong>${money(total)}</strong></div></div><p>This is an estimated jewellery amount. The shop will confirm the final price, GST, delivery charge and expected date after reviewing your request. No payment is taken now.</p>${rateNotice()}<button class="primary" data-action="checkout">Request this jewellery <span>↗</span></button>`:'<div class="empty"><h3>A little room for something lovely.</h3><p>Your bag is empty. Explore the collections to find your first piece.</p><button class="primary" data-action="close">Explore collections</button></div>');modalKind='bag'}
async function checkout(){if(!auth.state.ready){try{await auth.refresh()}catch(error){toast(error.message);return}}if(!db.cart.length)return showBag();if(!role)return login('checkout');if(!preferredName())return askPreferredName('checkout');return orderUI.checkout()}
function orders(){if(!role)return login('orders');return orderUI.list()}
function adminOrders(){if(isAdmin())return orderUI.list({admin:true})}
const orderUI=createOrderUI({auth,modal,esc,toast,preferredName,getBag:()=>db.cart.map(c=>{const p=db.products.find(p=>p.id===c.id);return {...p,qty:c.qty,estimate:price(p).total}}),clearBag:()=>{db.cart=[];persist();render()},refreshBag:async()=>{await loadMetadata();const items=await inventory.byIds(db.cart.map(c=>c.id));if(items.length!==db.cart.length)throw new Error('A piece is no longer available. Reopen your bag to review it.');cacheProducts(items)}});

function dashboard(){if(!isAdmin())return;modal('Your shop, at a glance',`<div class="notice">Categories, jewellery and photos are saved online and shared across devices. Only your verified admin account can edit them. Order requests are open. Review each request before issuing a final quote; advance payments are not connected yet.</div><div class="admin-tabs"><button data-action="manageCategories">Categories</button><button data-action="addJewel">Add jewellery</button><button data-action="settings">Rates & charges</button><button data-action="adminOrders">Order requests</button></div><div class="price-lines"><div><span>Jewellery pieces</span><strong>${categoryRows.reduce((sum,r)=>sum+Number(r.product_count),0)}</strong></div><div><span>Categories</span><strong>${db.categories.Gold.length+db.categories.Silver.length-2}</strong></div><div><span>Order requests</span><strong>Open for shop review</strong></div></div><h3>One owner. Full control.</h3><p>Only the verified shop account has administrator access. Other accounts cannot manage the shop. The database controls this permission; it cannot be selected during sign-in.</p><button class="secondary" data-action="importCatalogue">Import old browser catalogue</button>`)}
const coverKey=(m,c)=>JSON.stringify([m,c]);
const coverSearches=new Map();
let searchQueue=Promise.resolve();
const cleanText=value=>new DOMParser().parseFromString(String(value||''),'text/html').body.textContent.trim();
function safeHttps(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
function searchTerms(m,c){let name=c.normalize('NFKC').replace(/[_-]/g,' ').trim();const dollar=/\bdollars?\b/i.test(name);let term=name.replace(/\bpendents?\b/ig,'pendant');if(dollar)term+=' pendant Indian jewellery';return {query:`${m.toLowerCase()} ${term}`,fallback:null,words:dollar?['pendant','locket','thali']:name.toLowerCase().split(/\s+/).filter(w=>!['gold','silver','jewellery','jewelry','collection','collections','new'].includes(w)).map(w=>w.replace(/s$/,''))}}
async function queryCoverImages(query,words){const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:query+' filetype:bitmap',gsrnamespace:'6',gsrlimit:'24',prop:'imageinfo',iiprop:'url|size|extmetadata',iiurlwidth:'960',format:'json',origin:'*'});const response=await fetch('https://commons.wikimedia.org/w/api.php?'+params,{signal:AbortSignal.timeout(18000),credentials:'omit'});if(!response.ok)throw Error(response.status===429?'Image search is busy. Please try again shortly.':'Image search is unavailable. Please retry.');const body=await response.json();if(body.error)throw Error('The image search could not complete. Please retry.');const pages=Object.values(body.query?.pages||{});return pages.map(p=>{const info=p.imageinfo?.[0],meta=info?.extmetadata;if(!info||!meta)return null;const title=cleanText(meta.ObjectName?.value||p.title.replace(/^File:/,''));const description=cleanText(meta.ImageDescription?.value);const text=(p.title+' '+description).toLowerCase();if(/\bthali\b/i.test(query)&&!/(thali|thaali)/i.test(text))return null;const license=cleanText(meta.LicenseShortName?.value);const source=safeHttps(info.descriptionurl);const src=safeHttps(info.thumburl||info.url).split('?')[0];if(!src||!source||!/(cc0|cc.by|public domain|pd)/i.test(license)||/(noncommercial|\bnc\b|\bnd\b)/i.test(license))return null;if(Math.min(info.width||0,info.height||0)<450)return null;if(!words.length||!words.some(w=>text.includes(w)))return null;if(/\b(banknote|currency|ribbon|medal of honor|us-moh)\b/i.test(text))return null;let score=words.reduce((s,w)=>s+(p.title.toLowerCase().includes(w)?25:text.includes(w)?5:0),0);if(/museum|\bmet\b|bce|century|findid|archaeolog|ancient/i.test(p.title))score-=12;if(/jewell?ery|modern|studio/i.test(p.title))score+=12;return {id:String(p.pageid),src,title,creator:cleanText(meta.Artist?.value||'Creator not listed'),license,licenseUrl:safeHttps((meta.LicenseUrl?.value||'').replace(/^http:/,'https:')),source,score};}).filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,8)}
function coverRecord(m,c){return db.categorySearchResults?.[coverKey(m,c)]}
function categoryCover(m,c){const row=categoryRow(m,c);if(row?.cover?.src)return row.cover;const record=coverRecord(m,c);if(row?.first_photo)return {src:row.first_photo,source:'Jewellery photo'};return {src:null,source:coverSearches.has(coverKey(m,c))?'Searching for a matching picture…':isAdmin()?'Add a category picture':'Collection coming soon'}}
function refreshCoverUI(m,c){if(currentRoute?.screen==='categories'&&metal===m)render();const editor=$('#coverSearchEditor');if(editor?.dataset.category===c&&editor.dataset.metal===m)renderSearchResults(m,c)}
async function searchCategoryCover(m,c,{force=false,query=null}={}){if(!isAdmin())return null;const key=coverKey(m,c);if(coverSearches.has(key))return coverSearches.get(key);if(!force&&coverRecord(m,c))return coverRecord(m,c);const terms=searchTerms(m,c);const work=searchQueue.catch(()=>{}).then(async()=>{let results=[],actual=query||terms.query,error=null;try{results=await queryCoverImages(actual,query?searchTerms(m,query).words:terms.words);if(!results.length&&!query&&terms.fallback){actual=terms.fallback;results=await queryCoverImages(actual,query?searchTerms(m,query).words:terms.words)}}catch(e){error=e.name==='TimeoutError'?'Image search timed out. Please retry.':e.message}if(!db.categories[m].includes(c))return null;const old=coverRecord(m,c);const record=error&&old?.selected?{...old,error}:{query:actual,results,selected:results[0]||null,error,updated:new Date().toISOString()};db.categorySearchResults={...(db.categorySearchResults||{}),[key]:record};if(record.selected){try{await inventory.saveCover(categoryRow(m,c),record.selected);await loadMetadata()}catch(error){record.error=error.message;toast(error.message)}}return record}).finally(()=>{coverSearches.delete(key);refreshCoverUI(m,c)});coverSearches.set(key,work);searchQueue=work;return work}
function ensureCategoryCovers(m){}
function imageCredits(){const entries=[];for(const m of ['Gold','Silver']){for(const c of db.categories[m].filter(c=>c!=='All pieces')){const cover=categoryCover(m,c);if(cover.license&&cover.source)entries.push(`<section class="image-credit-entry"><h3>${esc(m)} · ${esc(c)}</h3>${coverCredit(cover)}</section>`)}}modal('Image credits',entries.length?entries.join(''):'<p>No externally attributed category pictures are currently selected.</p>')}
function coverCredit(cover){return cover.source&&cover.license?`<div class="cover-credit"><a href="${esc(cover.source)}" target="_blank" rel="noopener">${esc(cover.title)} · ${esc(cover.creator)}</a> · ${cover.licenseUrl?`<a href="${esc(cover.licenseUrl)}" target="_blank" rel="noopener">${esc(cover.license)}</a>`:esc(cover.license)} · Resized</div>`:''}
async function saveCategoryCover(m,c,src){if(!isAdmin())return false;return onlineChange(()=>inventory.saveCover(categoryRow(m,c),src?{src}:coverRecord(m,c)?.selected||{}),()=>refreshCoverUI(m,c))}
function renderSearchResults(m,c){const host=$('#liveCoverResults');if(!host)return;const record=coverRecord(m,c),busy=coverSearches.has(coverKey(m,c));host.innerHTML=busy?'<p class="search-status" role="status">Searching the web for matching jewellery pictures…</p>':record?.results?.length?`<p class="search-status">Results for “${esc(record.query)}”. The first match is selected automatically; choose another if you prefer.</p><div class="search-result-grid">${record.results.map((r,i)=>`<div><button class="search-result ${record.selected?.id===r.id?'chosen':''}" data-search-result="${i}" data-cover-name="${esc(c)}"><img src="${esc(r.src)}" alt="${esc(r.title)}" loading="lazy"><span>${esc(r.title)}</span><small>${record.selected?.id===r.id?'Selected':'Use this picture'}</small></button>${coverCredit(r)}</div>`).join('')}</div>`:`<p class="search-status" role="status">${esc(record?.error||'No suitable image found for this search. Try more specific words or upload a picture. No generic photo has been substituted.')}</p>`;const cover=categoryCover(m,c);$('#coverCurrent').innerHTML=cover.src?`<img class="cover-large" src="${esc(cover.src)}" alt="Current category cover">${coverCredit(cover)}`:'<div class="cover-empty">No picture selected</div>'}
function editCategoryCover(c){if(!isAdmin()||!db.categories[metal].includes(c))return;const m=metal;modal(`${c} · find a category picture`,`<div id="coverSearchEditor" data-category="${esc(c)}" data-metal="${m}"><div class="cover-editor"><div id="coverCurrent"></div><div><h3>Search for this category.</h3><p>Search uses your category name and metal. “Dollar” is interpreted as an Indian jewellery pendant, not currency.</p><form id="coverSearchForm"><label class="cover-query-label">Search words<input id="coverQuery" required maxlength="100" value="${esc(coverRecord(m,c)?.query||searchTerms(m,c).query)}"></label><button class="primary small" type="submit">Search pictures</button></form></div></div><div id="liveCoverResults" aria-live="polite"></div><label class="upload-area">Or upload a category picture<input id="categoryCoverFile" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="sample-note">Search results come from Wikimedia Commons; some jewellery styles may not be available. Category pictures are visual references, not shop inventory.</p><div class="form-actions"><button class="secondary" data-action="manageCategories">Back to categories</button></div></div>`);renderSearchResults(m,c);if(!coverRecord(m,c))searchCategoryCover(m,c).then(()=>{});$('#coverSearchForm').onsubmit=e=>{e.preventDefault();searchCategoryCover(m,c,{force:true,query:$('#coverQuery').value.trim()});renderSearchResults(m,c)};$('#categoryCoverFile').onchange=async e=>{const input=e.currentTarget,file=input.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Choose JPEG, PNG or WebP.');if(file.size>15*1024*1024)return toast('Choose an image under 15 MB.');input.disabled=true;try{const src=await compressPhoto(file);if(isAdmin()&&await saveCategoryCover(m,c,src)){renderSearchResults(m,c);toast('Category picture updated.')}}catch{toast('This image could not be read.')}finally{input.disabled=false;input.value=''}}}
function manageCategories(){if(!isAdmin())return;modal(`${metal} categories`,`<p>Add a name and the website searches for a matching picture. Each category has its own search; no common fallback image is used.</p><form id="categoryForm" class="form-grid"><label>New category<input name="category" id="categoryName" required maxlength="40" placeholder="e.g. Pendant or Dollars" autocomplete="off"></label><div style="align-self:end"><button class="primary small" type="submit" style="margin:0">Add & find picture</button></div><p class="full sample-note" id="newCoverNote">The search starts after you add the category.</p></form><div class="managed-category-list">${db.categories[metal].filter(c=>c!=='All pieces').map(c=>{const cover=categoryCover(metal,c);return `<div class="managed-category">${cover.src?`<img class="managed-cover" src="${esc(cover.src)}" alt="${esc(c)} cover" loading="lazy">`:'<div class="managed-cover cover-empty">No picture yet</div>'}<div class="managed-category-info"><strong>${esc(c)}</strong><small>${categoryCount(metal,c)} pieces</small><div class="managed-category-actions"><button class="text-button" data-cover-category="${esc(c)}">Search / change picture</button><button class="text-button" data-rename-category="${esc(c)}">Rename</button><button class="text-button danger" data-delete-category="${esc(c)}">Delete</button></div></div></div>`}).join('')}</div>`);$('#categoryName').oninput=e=>{const c=e.target.value.trim();$('#newCoverNote').textContent=c?'Will search: '+searchTerms(metal,c).query:'The search starts after you add the category.'};$('#categoryForm').onsubmit=async e=>{e.preventDefault();const value=new FormData(e.currentTarget).get('category').trim(),m=metal;if(!value)return;await onlineChange(()=>inventory.addCategory(m,value),()=>{searchCategoryCover(m,value);editCategoryCover(value);toast('Category saved online.')})}}


function editJewel(id){if(!isAdmin())return;const p=db.products.find(p=>p.id===id)||{name:'',metal,category:currentRoute?.category||db.categories[metal][1],purity:metal==='Gold'?'22K':'925',weight:'',chargeType:'fixed',charge:0,description:'',photos:[]};editorId=id||null;editorPhotos=[...p.photos];editorOriginals=p.photos.map((src,i)=>p.photo_originals?.[i]||src);modal(id?'Edit jewellery':'Add a little treasure',`<form id="jewelForm"><div class="form-grid"><label class="full">Jewellery name<input name="name" value="${esc(p.name)}" maxlength="80" required></label><label>Metal<select name="metal" id="editorMetal"><option ${p.metal==='Gold'?'selected':''}>Gold</option><option ${p.metal==='Silver'?'selected':''}>Silver</option></select></label><label>Category<select name="category" id="editorCategory" required></select></label><label>Purity<select name="purity" id="editorPurity"></select></label><label>Weight in grams<input name="weight" type="number" min="0.001" max="10000" step="0.001" value="${p.weight}" required></label><label>Shop charge type<select name="chargeType"><option value="fixed" ${p.chargeType==='fixed'?'selected':''}>Fixed amount (₹)</option><option value="gram" ${p.chargeType==='gram'?'selected':''}>Per gram (₹/g)</option><option value="percent" ${p.chargeType==='percent'?'selected':''}>Percentage of metal value (%)</option></select></label><label>Shop charge value<input name="charge" type="number" min="0" max="10000000" step="0.01" value="${p.charge}" required></label><label class="full">Description (optional)<textarea name="description" maxlength="1500">${esc(p.description)}</textarea></label></div><h3>Every angle tells a story.</h3><p>Upload several photos. The first is the main photo. Use the arrows to reorder and the star to make any photo the main image.</p><label class="upload-area">+ Add jewellery photos<input id="photoUpload" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div id="photoList" class="photo-list"></div><div class="notice">Up to 8 photos per jewel. Use Background on any photo for Warm Cream or Midnight Blue Velvet. Preview before applying; originals are kept when you save.</div><div class="form-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button type="submit" class="primary">${id?'Save changes':'Add jewellery'} <span>↗</span></button></div></form>`);
 const updateOptions=()=>{const m=$('#editorMetal').value;$('#editorCategory').innerHTML=db.categories[m].filter(c=>c!=='All pieces').map(c=>`<option ${c===p.category?'selected':''}>${esc(c)}</option>`).join('');$('#editorPurity').innerHTML=(m==='Gold'?['22K','18K']:['925']).map(v=>`<option ${v===p.purity?'selected':''}>${v}</option>`).join('')};updateOptions();$('#editorMetal').onchange=updateOptions;photoList();$('#photoUpload').onchange=async e=>{const files=[...e.target.files];if(files.length+editorPhotos.length>8)return toast('Please use a maximum of 8 photos.');const submit=$('#jewelForm button[type="submit"]');submit.disabled=true;try{for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Please choose JPEG, PNG or WebP photos.');if(file.size>15*1024*1024)throw Error('Each photo must be under 15 MB.');const src=await compressPhoto(file);editorPhotos.push(src);editorOriginals.push(src)}photoList()}catch(err){toast(err.message)}finally{submit.disabled=false;e.target.value=''}};
 $('#jewelForm').onsubmit=async e=>{e.preventDefault();if(!isAdmin())return;if(!editorPhotos.length)return toast('Add at least one photo to continue.');const f=new FormData(e.currentTarget);const item={id:editorId||crypto.randomUUID(),name:f.get('name').trim(),metal:f.get('metal'),category:f.get('category'),purity:f.get('purity'),weight:Number(f.get('weight')),chargeType:f.get('chargeType'),charge:Number(f.get('charge')),description:f.get('description').trim(),photos:[...editorPhotos],photo_originals:[...editorOriginals],isSample:p.isSample||false,tag:p.tag||'NEW TO THE COLLECTION'};if(!item.name||!item.category)return toast('Please add a name and category.');if(item.chargeType==='percent'&&item.charge>100)return toast('Percentage must be between 0 and 100.');await onlineChange(()=>inventory.saveProduct(item,editorId?p.version:null),()=>{$('#modal').close();navigate(routePath(item.metal,item.category));toast('Jewellery saved online.')})};

}
function compressPhoto(file){return new Promise((resolve,reject)=>{const src=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=Math.max(1,img.width*scale);canvas.height=Math.max(1,img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(src);resolve(canvas.toDataURL('image/jpeg',.78))};img.onerror=()=>{URL.revokeObjectURL(src);reject(Error('This image could not be read.'))};img.src=src})}
function photoList(){$('#photoList').innerHTML=editorPhotos.map((s,i)=>`<div class="photo-item"><img src="${esc(s)}" alt="Uploaded photo ${i+1}"><button class="photo-background" type="button" data-photo-background="${i}">Background</button><small>${i===0?'MAIN PHOTO':'PHOTO '+(i+1)}</small><button type="button" data-photo-left="${i}" aria-label="Move photo left" ${i===0?'disabled':''}>←</button><button type="button" data-photo-main="${i}" aria-label="Set as main photo">☆</button><button type="button" data-photo-remove="${i}" aria-label="Remove photo">×</button></div>`).join('')}
function settings(){if(!isAdmin())return;modal('Checkout settings',`<div class="notice">Gold and silver rates update automatically from Live Chennai every five minutes. Shop charges are set on each jewel. Order requests are open; advance payment collection is not connected yet.</div><form id="settingsForm"><div class="form-grid"><label>GST percentage (estimate)<input name="gst" type="number" min="0" max="100" step="0.01" value="${db.gst}" required></label><label>Delivery charge (estimate ₹)<input name="delivery" type="number" min="0" max="100000" step="1" value="${db.delivery}" required></label></div><p>GST is applied to jewellery value plus shop charge. Delivery is shown separately.</p><button class="primary" type="submit">Save shop settings</button></form>`);$('#settingsForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await onlineChange(()=>inventory.saveSettings({gst:Number(f.get('gst')),delivery:Number(f.get('delivery'))},settingsRow.version),()=>{closeModal();toast('Checkout settings saved online.')})}}


function importCatalogue(){
 if(!isAdmin())return;
 const saved=legacyCatalogue;
 if(!saved?.categories){modal('Import old browser catalogue','<p>No earlier catalogue was found on this device. You can add jewellery directly to the shared catalogue.</p>');return}
 const items=Array.isArray(saved.products)?saved.products:[];
 modal('Review your browser catalogue',`<p>This imports saved categories and the pieces you select from this device. Existing shared pieces are not overwritten. The original browser backup stays intact.</p><form id="importForm"><div class="import-items">${items.map((p,i)=>`<label class="checks"><input type="checkbox" name="piece" value="${i}" ${base.products.some(b=>b.id===p.id)?'':'checked'}><span>${esc(p.name)} · ${esc(p.metal)} / ${esc(p.category)}${base.products.some(b=>b.id===p.id)?' · earlier sample piece':''}</span></label>`).join('')||'<p>No saved pieces on this device. Categories can still be imported.</p>'}</div><div class="notice">Earlier sample pieces are unselected. If selected, they remain visibly marked as illustrative samples. Only category and product data is imported—not accounts, orders, or rates.</div><p id="importStatus" role="status"></p><button class="primary" type="submit">Import selected pieces & categories</button></form>`);
 $('#importForm').onsubmit=async e=>{e.preventDefault();const selected=new FormData(e.currentTarget).getAll('piece').map(i=>items[Number(i)]);await onlineChange(async()=>{
   const imported=new Set(await inventory.importedIds());let count=0;
   for(const m of ['Gold','Silver'])for(const c of Array.isArray(saved.categories[m])?saved.categories[m]:[]){if(c==='All pieces')continue;if(!categoryRows.some(r=>r.metal===m&&r.name.toLowerCase()===c.toLowerCase())){await inventory.addCategory(m,c);await loadMetadata()}}
   for(const item of selected){
     const legacyId=String(item.id);if(imported.has(legacyId))continue;
     $('#importStatus').textContent=`Uploading piece ${++count} of ${selected.length}…`;
     const row=categoryRows.find(r=>r.metal===item.metal&&r.name.toLowerCase()===String(item.category).toLowerCase());if(!row)throw Error('A saved piece has no valid category. Add its category first.');
     await inventory.saveProduct({...item,id:crypto.randomUUID(),category:row.name,isSample:base.products.some(b=>b.id===item.id)},null,legacyId);
   }
   // Copy explicit saved category pictures after products. This can be retried independently.
   for(const m of ['Gold','Silver'])for(const c of Array.isArray(saved.categories[m])?saved.categories[m]:[]){if(c==='All pieces')continue;const row=categoryRows.find(r=>r.metal===m&&r.name.toLowerCase()===c.toLowerCase());const cover=saved.categoryCovers?.[coverKey(m,c)]?{src:saved.categoryCovers[coverKey(m,c)]}:saved.categorySearchResults?.[coverKey(m,c)]?.selected;if(row&&cover?.src&&!row.cover?.src){await inventory.saveCover(row,cover);await loadMetadata()}}
 },()=>{dashboard();toast('Selected catalogue data is saved online. Your browser backup is unchanged.')})};
}

const actions={adminOrders,importCatalogue,retryCatalogue:()=>syncCatalogue().catch(e=>toast(e.message)),editName:()=>askPreferredName('account'),checkoutName:()=>askPreferredName('checkout'),signOut,imageCredits,shopInfo,goHome:()=>navigate('#/'),backCatalog:()=>navigate(routePath(metal,category)),backCategories:()=>navigate(routePath(metal)),close:closeModal,policy,rates,dashboard,manageCategories,addJewel:()=>editJewel(),settings,orders,checkout,prevPhoto:()=>gallery(galleryIndex-1),nextPhoto:()=>gallery(galleryIndex+1),zoom:()=>{const p=activeProduct;modal(p.name,`<img class="full-image" src="${esc(p.photos[galleryIndex])}" alt="${esc(p.name)}"><button class="secondary" data-product="${p.id}">← Back to jewellery</button>`)}};
document.addEventListener('click',async e=>{const t=e.target.closest('button,[data-action],[data-home]');if(!t)return;const d=t.dataset;if(d.photoBackground!==undefined&&isAdmin()){const i=Number(d.photoBackground),form=$('#jewelForm');openPhotoStudio({original:editorOriginals[i],current:editorPhotos[i],onApply:src=>{if(isAdmin()&&form===$('#jewelForm')){editorPhotos[i]=src;photoList()}}});return}if(d.coverCategory&&isAdmin()){editCategoryCover(d.coverCategory);return}if(d.searchResult!==undefined&&isAdmin()){const record=coverRecord(metal,d.coverName),picked=record?.results[Number(d.searchResult)];if(picked){record.selected=picked;if(await saveCategoryCover(metal,d.coverName,null))toast('Category picture saved online.')}return}if(d.home!==undefined){e.preventDefault();navigate('#/');return}if(d.page){pageNumber=Number(d.page);loadCataloguePage();$('#catalogTitle').scrollIntoView({behavior:'instant'});return}if(d.action&&actions[d.action])return actions[d.action]();if(d.metal){navigate(routePath(d.metal));return}if(d.category){navigate(routePath(metal,d.category));return}if(d.product)showProduct(d.product);if(d.photo!==undefined)gallery(Number(d.photo));if(d.addBag)addBag(d.addBag);if(d.edit)editJewel(d.edit);if(d.delete&&isAdmin()){const item=db.products.find(p=>p.id===d.delete);if(item&&confirm('Delete this jewellery piece from the shared catalogue?'))await onlineChange(()=>inventory.deleteProduct(item),()=>{db.cart=db.cart.filter(c=>c.id!==d.delete);persist();toast('Jewellery deleted online.')})}if(d.remove){db.cart=db.cart.filter(c=>c.id!==d.remove);persist();render();showBag()}if(d.deleteCategory&&isAdmin()){const row=categoryRow(metal,d.deleteCategory);if(row&&confirm('Delete category '+d.deleteCategory+'?'))await onlineChange(()=>inventory.deleteCategory(row),manageCategories)}if(d.renameCategory&&isAdmin()){const row=categoryRow(metal,d.renameCategory),next=prompt('New category name',d.renameCategory)?.trim();if(!next||next===d.renameCategory)return;if(next.length>40)return toast('Use a category name under 40 characters.');await onlineChange(()=>inventory.renameCategory(row,next),manageCategories)}if(d.photoLeft!==undefined&&isAdmin()){const i=Number(d.photoLeft);[editorPhotos[i-1],editorPhotos[i]]=[editorPhotos[i],editorPhotos[i-1]];[editorOriginals[i-1],editorOriginals[i]]=[editorOriginals[i],editorOriginals[i-1]];photoList()}if(d.photoMain!==undefined&&isAdmin()){editorPhotos.unshift(editorPhotos.splice(Number(d.photoMain),1)[0]);editorOriginals.unshift(editorOriginals.splice(Number(d.photoMain),1)[0]);photoList()}if(d.photoRemove!==undefined&&isAdmin()){editorPhotos.splice(Number(d.photoRemove),1);editorOriginals.splice(Number(d.photoRemove),1);photoList()}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});$('#accountBtn').onclick=account;
$('#adminNav').onclick=dashboard;$('#bagBtn').onclick=showBag;$('#policyBtn').onclick=policy;$('#policyStrip').onclick=policy;$('#footerPolicy').onclick=policy;$('#ratesBtn').onclick=rates;$('#addCategory').onclick=manageCategories;$('#addJewel').onclick=()=>editJewel();let searchTimer;$('#search').oninput=()=>{pageNumber=1;clearTimeout(searchTimer);searchTimer=setTimeout(loadCataloguePage,300)};$('#sort').onchange=()=>{pageNumber=1;loadCataloguePage()};$('#searchBtn').onclick=()=>{$('#search').scrollIntoView();$('#search').focus()};$('#backBtn').onclick=goBack;
