let rateRefreshBusy=false;
async function refreshVisibleRates(){
 if(document.hidden||mutationBusy||rateRefreshBusy)return;
 rateRefreshBusy=true;
 try{
  const before=JSON.stringify(settingsRow),kind=modalKind,id=activeProduct?.id,index=galleryIndex;
  await loadMetadata();render();
  if(before!==JSON.stringify(settingsRow)){
   if($('#modal').open&&kind===modalKind){
    if(kind==='rates')rates();
    else if(kind==='product'&&id){drawProduct(id);gallery(index)}
    else if(kind==='bag')await showBag();
   }
   if(!$('#modal').open)await loadCataloguePage();
  }
 }catch{ $('#rateStatus').textContent='Connection interrupted · showing previously loaded rates';$('.demo-label').textContent='CHECK DELAYED'; }
 finally{rateRefreshBusy=false}
}
setInterval(refreshVisibleRates,60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshVisibleRates()});
